import { mul, type Mat } from "./affine";
import { faceMatrix } from "./visor-geometry";
/**
 * Fighter portraits for dialogue cards, plan chips, pick cards, the site's bot pages and share images (#18, #85):
 * the plush brawler as in the game, as one self-contained SVG string (no DOM, no Pixi: the server draws them too).
 *
 * - The body: the BALANCED build's idle first frame (portraits.ts, generated by tools/art/plush_pack.py),
 *   two PNG layers: the suit, mitts and rim rendered neutral grey, colored here by an SVG gradient map (the same
 *   ramp as the game's filter, plush-ramp.ts), and the fixed parts on top.
 * - The marks: the fighter's major and minor marks, each placed by the head (or torso) anchors, as in the game.
 * - The face: the code LED dots (bot.ts drawVisor, no glass), mapped onto the rendered visor.
 */
import type { Identity, Mark } from "../sim/identity";
import type { MoraleState } from "../sim/morale";
import { PORTRAIT } from "./portraits";
import { drawVisor, faceFor, FEET_Y, type FaceMood, type Lod } from "./bot";
import { hash } from "./hash";
import { BEHIND_MARKS, TORSO_MARKS } from "./plush-motion";
import { plushRamp, RAMP_STOPS } from "./plush-ramp";
import { SvgPen } from "./svgPen";

export type Mood = "fight" | "win" | MoraleState | "hit" | "stun" | "ko";

type Pt = readonly number[];
const PPM = PORTRAIT.ppm;
const G = PORTRAIT.ground;
/** cell pixels -> the fighter's local meters (feet on y = FEET_Y, y down) */
const meters = (q: Pt): [number, number] => [(q[0]! - G[0]!) / PPM, FEET_Y + (q[1]! - G[1]!) / PPM];
const inv = (m: Mat): Mat => {
  const det = m[0] * m[3] - m[1] * m[2];
  return [m[3] / det, -m[1] / det, -m[2] / det, m[0] / det, (m[2] * m[5] - m[3] * m[4]) / det, (m[1] * m[4] - m[0] * m[5]) / det];
};
/** the affine frame of a bone's three projected anchors (center, +x, +z), in local meters */
const anchor = (pts: readonly Pt[]): Mat => {
  const [c, x, z] = pts.map(meters) as [[number, number], [number, number], [number, number]];
  return [x[0] - c[0], x[1] - c[1], z[0] - c[0], z[1] - c[1], c[0], c[1]];
};
const f3 = (n: number) => +n.toFixed(4);
const mat = (m: Mat) => `matrix(${m.map(f3).join(" ")})`;

const FACE_M = faceMatrix(PORTRAIT.body.visor.map(meters));

/** The gradient map as an SVG filter: luminance -> the fighter's ramp (deep shadow, shadow, color, highlight). */
function rampFilter(id: string, color: number): string {
  const ramp = plushRamp(color).map((c) => [((c >> 16) & 255) / 255, ((c >> 8) & 255) / 255, (c & 255) / 255]);
  const stops = [0, ...RAMP_STOPS];
  const at = (l: number, ch: number) => {
    let i = 0;
    while (i < stops.length - 2 && l > stops[i + 1]!) i++;
    const t = Math.min(1, Math.max(0, (l - stops[i]!) / (stops[i + 1]! - stops[i]!)));
    return ramp[i]![ch]! + (ramp[i + 1]![ch]! - ramp[i]![ch]!) * t;
  };
  const table = (ch: number) => Array.from({ length: 33 }, (_, k) => f3(at(k / 32, ch))).join(" ");
  return `<filter id="${id}" color-interpolation-filters="sRGB" x="0" y="0" width="1" height="1"><feColorMatrix type="matrix" values="0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0.299 0.587 0.114 0 0 0 0 0 1 0"/><feComponentTransfer><feFuncR type="table" tableValues="${table(0)}"/><feFuncG type="table" tableValues="${table(1)}"/><feFuncB type="table" tableValues="${table(2)}"/></feComponentTransfer></filter>`;
}

interface PartImg { x: number; y: number; w: number; h: number; tint: string; fixed: string }
/** One part's two layers, placed in local meters (its cell position), the tint one through the ramp filter. */
function layers(p: PartImg, filter: string): string {
  const [x, y] = meters([p.x, p.y]);
  const w = f3(p.w / PPM), h = f3(p.h / PPM);
  const at = `x="${f3(x)}" y="${f3(y)}" width="${w}" height="${h}" preserveAspectRatio="none"`;
  return `<image ${at} href="${p.tint}" filter="url(#${filter})"/><image ${at} href="${p.fixed}"/>`;
}

/** A mark's layers, moved from its render pose onto the body's head (torso) anchors. */
function markSvg(m: Mark, filter: string): string {
  const mk = (PORTRAIT.marks as Record<string, (PartImg & { head: readonly Pt[]; torso: readonly Pt[] }) | undefined>)[m];
  if (!mk) return "";
  const bone = TORSO_MARKS.has(m) ? "torso" : "head";
  const t = mul(anchor(PORTRAIT.body[bone]), inv(anchor(mk[bone])));
  return `<g transform="${mat(t)}">${layers(mk, filter)}</g>`;
}

let seq = 0;
/** A whole bot; the bust is the head only (for small HUD chips). */
const VIEW_FULL = "-0.86 -1.32 1.74 2.3";

/**
 * The portrait of a fighter's identity. `lod` "tiny" is for small chips: the head only, square dots. `t` picks the
 * moment (blink, spinner, KO frame).
 */
export function portraitSvg(id: Identity, mood: Mood = "fight", lod: Lod = "full", t = 0.3): string {
  const face: FaceMood = mood === "fight" ? "confident" : mood;
  const bust = lod === "tiny";
  const fid = `kbp${(hash(id.name) >>> 0).toString(36)}${(++seq).toString(36)}`;
  const minor = id.minor ?? "none";
  const pen = new SvgPen();
  drawVisor(pen, id, faceFor(face, t, hash(id.name), id.eyes, { lookX: bust ? 0 : 1, koT: 1.2 }), lod, false);
  const behind = BEHIND_MARKS.has(id.mark) ? markSvg(id.mark, fid) : "";
  const front = BEHIND_MARKS.has(id.mark) ? "" : markSvg(id.mark, fid);
  const minorSvg = minor !== "none" ? markSvg(minor, fid) : "";
  let view = VIEW_FULL;
  if (bust) {
    const [cx, cy] = meters(PORTRAIT.body.head[0]!);
    view = `${f3(cx - 0.62)} ${f3(cy - 0.78)} 1.24 1.2`;
  }
  const shadow = bust ? "" : `<ellipse cx="0" cy="0.86" rx="0.5" ry="0.06" fill="rgba(0,0,0,.4)"/>`;
  return `<svg viewBox="${view}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs>${rampFilter(fid, id.color)}</defs>${shadow}${behind}${layers(PORTRAIT.body, fid)}${minorSvg}<g transform="${mat(FACE_M)}">${pen.toSvg()}</g>${front}</svg>`;
}
